ValidationRule.errorConditionFormula:
AND(
    NOT(ISNEW()),
    OR(
        ISCHANGED(Event__c),
        AND(
            ISCHANGED(Attendee__c),
            OR(
                ISPICKVAL(Registration_Status__c, "Confirmed"),
                ISPICKVAL(Registration_Status__c, "Cancelled")
            )
        )
    )
)
